SELECT 'gongkao', '词汇理解', 'kp-sl-reading-vocab', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "词汇理解：提炼核心词"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心心法：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "申论不是文学创作，所有的核心词都在材料里！绝对不能自己生造词汇。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、找词原则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "申论材料是政府公文、新闻报道或学者论述。阅卷老师批改申论只有一种方式：【按关键词给分】。"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "规范词优先：材料里出现的政策词汇、专业术语（如“放管服”、“供给侧改革”、“源头治理”），哪怕你不懂什么意思，直接抄下来就是得分点！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "高频词必抄：一段话里反复出现 3 次以上的名词，绝对是命题人想让你写的答案核心。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "关联词后找词：在“但是”、“因此”、“由于”、“关键在于”后面的核心词，含金量极高。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、实战避坑"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "乱用自己的话总结：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "材料写“村里修了路，建了网，拉了自来水”。你如果在答题卡上自己总结写“改善了农村面貌”，阅卷标准答案如果是“完善了基础设施建设”，你可能一分拿不到。申论的最高境界是【精准抄材料的规范提法】。"}]}]}]}$$ AS jsonb), NULL, '词汇理解的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "阅读理解", "找词法"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_reading_vocab", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
